BEGIN;
SELECT pg_advisory_xact_lock(20261101033);
CREATE TABLE IF NOT EXISTS platform_setup_backups(version TEXT PRIMARY KEY,catalog JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_apps(app_id UUID PRIMARY KEY REFERENCES apps(id) ON DELETE CASCADE,category TEXT NOT NULL,lifecycle TEXT NOT NULL CHECK(lifecycle IN ('Live','Test environment','Development','Local','Pending')),audience TEXT NOT NULL CHECK(audience IN ('public','staff','admin')),launch_url TEXT CHECK(launch_url IS NULL OR launch_url ~ '^https://[^[:space:]]+$'),login_mode TEXT NOT NULL DEFAULT 'Separate sign-in',updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_integrations(id TEXT PRIMARY KEY,source_slug TEXT NOT NULL,target_slug TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Connected','Link only','Planned')),details TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
-- Stable app identity mapping is reserved for verified linking; matching email alone never grants access.
CREATE TABLE IF NOT EXISTS platform_account_links(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),hub_user_id UUID REFERENCES users(id),hub_customer_id UUID REFERENCES customer_accounts(id),app_id UUID NOT NULL REFERENCES apps(id),external_subject TEXT NOT NULL,verified_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((hub_user_id IS NOT NULL)::int+(hub_customer_id IS NOT NULL)::int=1),UNIQUE(app_id,external_subject));
COMMIT;
